	};
	{
		reg.exe add "HKLM\Software\Policies\Microsoft\Edge\Recommended" /v BackgroundModeEnabled /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\Software\Policies\Microsoft\Edge\Recommended" /v StartupBoostEnabled /t REG_DWORD /d 0 /f;
	};
	{
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows NT\CurrentVersion\SystemRestore" /v SystemRestorePointCreationFrequency /t REG_DWORD /d 0 /f
	};
	{
		Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\SetStartPins.ps1' -Raw | Invoke-Expression;
	};
	{
		Get-Content -LiteralPath 'C:\Windows\Setup\Scripts\unattend-01.ps1' -Raw | Invoke-Expression;
	};
	{
		# 1. Desactivar el almacenamiento reservado mediante DISM
		dism.exe /Online /Set-ReservedStorageState /State:Disabled /NoRestart | Out-Null;

		# 2. Asegurar en el registro que no se vuelva a inicializar tras actualizaciones
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\ReserveManager" /v ShippedWithReserves /t REG_DWORD /d 0 /f;
		reg.exe add "HKLM\SOFTWARE\Microsoft\Windows\CurrentVersion\ReserveManager" /v PassedPolicy /t REG_DWORD /d 0 /f;
	};
	{
		# Deshabilitar servicios de telemetria, rastreo y funciones prescindibles
		$servicesToDisable = @(
			"DiagTrack",          # Experiencias del usuario y telemetria
			"dmwappushservice",   # Enrutamiento de mensajes WAP (telemetria)
			"MapsBroker",         # Gestor de mapas descargados
			"RetailDemo",         # Servicio de demostracion de tienda
			# "SensorService",      # Sensores de orientacion (innecesario en PCs de escritorio)
			"TroubleshootingSvc", # Servicio de diagnostico y resolucion de problemas
			"wisvc"               # Windows Insider Program
		)

		foreach ($svc in $servicesToDisable) {
			Stop-Service -Name $svc -Force -ErrorAction SilentlyContinue
			Set-Service -Name $svc -StartupType Disabled -ErrorAction SilentlyContinue
		}
	};
	{
		# Registrar tarea con privilegios elevados para Launcher.ps1

		$ErrorActionPreference = 'Stop'

		$taskName = 'FirstLogonGUI_Launcher_Task'
		$launcherPath = 'C:\Windows\Setup\Scripts\Launcher.ps1'
		$psPath = "$env:WINDIR\System32\WindowsPowerShell\v1.0\powershell.exe"

		if (-not (Test-Path -LiteralPath $launcherPath -PathType Leaf)) {
			throw "No existe Launcher.ps1: $launcherPath"
		}

		$psArgs = "-NoProfile -ExecutionPolicy Bypass -File `"$launcherPath`""

		$action = New-ScheduledTaskAction `
			-Execute $psPath `
			-Argument $psArgs

		# Crear el principal mediante SID, sin nombres localizados
		$adminSid = New-Object System.Security.Principal.SecurityIdentifier('S-1-5-32-544')

		$principal = New-ScheduledTaskPrincipal `
			-GroupId $adminSid.Value `
			-RunLevel Highest

		$trigger = New-ScheduledTaskTrigger -AtLogOn

		$settings = New-ScheduledTaskSettingsSet `
			-AllowStartIfOnBatteries `
			-DontStopIfGoingOnBatteries `
			-StartWhenAvailable


		Register-ScheduledTask `
			-TaskName $taskName `
			-Action $action `
			-Trigger $trigger `
			-Principal $principal `
			-Settings $settings `
			-Force `
			-ErrorAction Stop

		Get-ScheduledTask -TaskName $taskName -ErrorAction Stop |
			Format-List TaskName, TaskPath, State
	};
);

& {	   
  [float] $complete = 0;
  [float] $increment = 100 / $scripts.Count;
  foreach( $script in $scripts ) {
    Write-Progress -Activity 'Running scripts to customize your Windows installation. Do not close this window.' -PercentComplete $complete;
    '*** Will now execute command «{0}».' -f $(
      $str = $script.ToString().Trim() -replace '\s+', ' ';
      $max = 100;
      if( $str.Length -le $max ) {
        $str;
      } else {
        $str.Substring( 0, $max - 1 ) + '…';
      }
    );
    $start = [datetime]::Now;
    & $script;
    '*** Finished executing command after {0:0} ms.' -f [datetime]::Now.Subtract( $start ).TotalMilliseconds;
    "`r`n" * 3;
    $complete += $increment;
  }
} *>&1 >> "C:\Windows\Setup\Scripts\Specialize.log";

