		# Pausa de 3 segundos para que Explorer termine de levantar el escritorio con el tema cargado
		Start-Sleep -Seconds 3;

		# Disparar la tarea elevada (corre como Administrador directo, sin ventana de UAC)
		Start-Process -FilePath "schtasks.exe" `
			-ArgumentList "/run /tn `"FirstLogonGUI_Launcher_Task`"" `
			-WindowStyle Hidden;
	};
);

