# Función de comprobación de red
function Test-InternetConnection {
    try {
        $test = Invoke-WebRequest -Uri "https://www.google.com" -UseBasicParsing -TimeoutSec 5
        return $true
    } catch {
        return $false
    }
}

# Variables de reintento claramente separadas
$maxRetries = 5;
$retry = 0;

while (-not (Test-InternetConnection)) {
    Write-Host "No hay conexión a Internet. Reintentando en 5 segundos... ($($retry + 1)/$maxRetries)" -ForegroundColor Yellow
    Start-Sleep -Seconds 5
    $retry++
    if ($retry -ge$maxRetries) {
        Write-Host "No se pudo establecer conexión a Internet. Abortando descarga." -ForegroundColor Red
        exit 1
    }
}

Write-Host "Conexión a Internet detectada. Iniciando descargas..." -ForegroundColor Green

# Procesamiento de descargas
foreach ($item in $downloads) {
    $fileName =$item.FileName
    $url =$item.Url
    $execute =$item.Execute

    if ([string]::IsNullOrWhiteSpace($fileName)) {
        Write-Host "Error: Nombre de archivo no definido para $url" -ForegroundColor Red
        continue
    }

    $targetPath = "$scriptDir\$fileName"

    try {
        Write-Host "Descargando $fileName..." -ForegroundColor Cyan
        Invoke-WebRequest -Uri $url -OutFile "$targetPath" -UseBasicParsing -ErrorAction Stop

        Unblock-File -Path "$targetPath" -ErrorAction SilentlyContinue
        #Write-Host "$fileName descargado y desbloqueado exitosamente." -ForegroundColor Green

        # Solo se ejecuta si Execute está marcado en $true
        if ($execute -eq$true) {
            Write-Host "Ejecutando $fileName..." -ForegroundColor Gray
            Start-Process -FilePath "powershell.exe" -ArgumentList "-ExecutionPolicy Bypass -NoProfile -File `"$targetPath`"" -Wait
        } else {
            Write-Host "$fileName descargado para ejecución posterior (omitida ejecución inmediata)." -ForegroundColor DarkGray
        }

    } catch {
        Write-Host "Error durante el procesamiento de ${fileName}:$_" -ForegroundColor Red
    }
}

