regroundColor Yellow if (Test-Path $TempFile) { Remove-Item $TempFile -Force } Invoke-WebRequest ` -Uri $DownloadUrl ` -Headers $Headers ` -OutFile $TempFile if (-not (Test-Path $TempFile)) { Write-Host "La descarga falló." -ForegroundColor Red exit 1 } $FileSize = (Get-Item $TempFile).Length if ($FileSize -lt 1MB) { Write-Host "El archivo descargado parece inválido." -ForegroundColor Red Remove-Item $TempFile -Force exit 1 } Write-Host "Descarga completada." -ForegroundColor Green Write-Host "Tamaño: $([math]::Round($FileSize / 1MB, 2)) MB" # ------------------------------------------------------------ # 4. Ejecutar MSI # ------------------------------------------------------------ Write-Host "" Write-Host "[4/4] Ejecutando instalador..." -ForegroundColor Yellow Write-Host "" $Arguments = "/i `"$TempFile`" /Passive" $Process = Start-Process ` -FilePath "msiexec.exe" ` -ArgumentList $Arguments ` -Wait ` -PassThru Write-Host "" if ($Process.ExitCode -eq 0) {
# Cerrar únicamente la ventana visible de RustDesk; no terminar sus procesos # ni el servicio que mantiene la conexión en segundo plano. Get-Process -Name 'rustdesk' -ErrorAction SilentlyContinue | Where-Object { $_.MainWindowHandle -ne 0 } | ForEach-Object { $null = $_.CloseMainWindow() }
Write-Host "============================================" -ForegroundColor Green Write-Host " RustDesk $Version instalado correctamente" -ForegroundColor Green Write-Host "============================================" -ForegroundColor Green } elseif ($Process.ExitCode -eq 3010) { Write-Host "============================================" -ForegroundColor Yellow Write-Host "Instalación correcta. Es necesario reiniciar." -ForegroundColor Yellow Write-Host "============================================" -ForegroundColor Yellow } else { Write-Host "============================================" -ForegroundColor Red Write-Host "La instalación terminó con código: $($Process.ExitCode)" -ForegroundColor Red Write-Host "============================================" -ForegroundColor Red } # ------------------------------------------------------------ # Limpieza # ------------------------------------------------------------ Remove-Item $TempFile -Force -ErrorAction SilentlyContinue

# ==========================================================
# STORE + WINGET INSTALLER TODO EN UNO
# Orden:
#   1) Microsoft Store (solo LTSC/IoT)
#   2) VCLibs
#   3) Windows App Runtime
#   4) Winget (Última versión desde GitHub)
# ==========================================================

# TLS 1.2 obligatorio
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$BasePath = "$env:TEMP\WingetFullInstall"
New-Item $BasePath -ItemType Directory -Force | Out-Null
$WingetLogPath = "$env:TEMP\InstallWinget.log"

function Write-WingetLog {
    param(
        [Parameter(Mandatory = $true)][string]$Message,
        [System.Management.Automation.ErrorRecord]$ErrorRecord
    )

    $entry = "[$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss')] $Message"
    if ($ErrorRecord) {
        $entry += [Environment]::NewLine + ($ErrorRecord | Format-List * -Force | Out-String).TrimEnd()
        $entry += [Environment]::NewLine + "Exception details: " + $ErrorRecord.Exception.ToString()
        if ($ErrorRecord.ScriptStackTrace) {
            $entry += [Environment]::NewLine + "Script stack: " + $ErrorRecord.ScriptStackTrace
        }
    }

    try {
        Add-Content -LiteralPath $WingetLogPath -Value $entry -Encoding UTF8 -ErrorAction Stop
    }
    catch {
        Write-Warning "No se pudo escribir el log de Winget en '$WingetLogPath': $($_.Exception.Message)"
        Write-Host $entry
    }
}

# ==========================================================
# FUNCION → VALIDAR SI COMPONENTE APPX EXISTE
# ==========================================================
function Test-AppxPackageInstalled {
    param(
        [string]$PackageName
    )
    return $null -ne (Get-AppxPackage -AllUsers $PackageName -ErrorAction SilentlyContinue)
}

# ==========================================================
# FUNCION → INSTALAR MICROSOFT STORE (LTSC / IoT)
# ==========================================================
function Install-StoreIfNeeded {

    $OfflineFolder = "$PSScriptRoot\StoreOffline"
    $TempDir       = "$BasePath\StorePack"
    $ZipFile       = "$BasePath\store_pack.zip"
    $CmdName       = "Add-Store.cmd"

    $cv = Get-ItemProperty "HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion"
    $edition = $cv.EditionID

    $esLTSC = @("EnterpriseS","EnterpriseSN","IoTEnterpriseS") -contains $edition

    Write-Host "Edición detectada: $edition"

    if (-not $esLTSC) {
        Write-Host "No es LTSC/IoT → se omite instalación de Store"
        return
    }

    if (Test-AppxPackageInstalled "Microsoft.WindowsStore") {
        Write-Host "Microsoft Store ya instalada → se omite"
        return
    }

    Write-Host "Instalando Microsoft Store..."

    Remove-Item $TempDir -Recurse -Force -ErrorAction SilentlyContinue
    New-Item $TempDir -ItemType Directory | Out-Null

    # ===============================
    # OFFLINE primero
    # ===============================
    if (Test-Path $OfflineFolder) {
        Write-Host "Modo OFFLINE detectado"
        Copy-Item "$OfflineFolder\*" $TempDir -Recurse -Force
    }
    else {
        Write-Host "Descargando última versión de la Store desde GitHub..."

        try {
            $latest = Invoke-RestMethod `
                "https://api.github.com/repos/mggons93/LTSC_STORE/releases/latest" `
                -ErrorAction Stop

            $StoreZipURL = $latest.zipball_url

            Write-Host "Versión: $($latest.tag_name)"

            Invoke-WebRequest $StoreZipURL -OutFile $ZipFile -UseBasicParsing -ErrorAction Stop
            Expand-Archive $ZipFile -DestinationPath $TempDir -Force
        }
        catch {
            Write-Host "ERROR descargando Microsoft Store → se omite"
            Write-Host $_.Exception.Message
            return
        }
    }

    # ===============================
    # Ejecutar Add-Store.cmd
    # ===============================
    $cmdPath = Get-ChildItem $TempDir -Recurse -Filter $CmdName |
               Select-Object -First 1 -ExpandProperty FullName

    if ($cmdPath) {
        Start-Process $cmdPath -Verb RunAs -Wait
    }
    else {
        Write-Host "No se encontró Add-Store.cmd"
    }
}

# ==========================================================
# FUNCION → INSTALAR WINGET CON VALIDACIONES
# ==========================================================
function Test-WingetInstalled {
    if (-not (Get-Command winget -ErrorAction SilentlyContinue)) {
        return $false
    }

    try {
        $null = & winget --version 2>$null
        return $LASTEXITCODE -eq 0
    }
    catch {
        return $false
    }
}

function Install-Winget {

    Write-Host "Verificando componentes de Winget..."

    $VCLibsUrl  = "https://aka.ms/Microsoft.VCLibs.x64.14.00.Desktop.appx"
    $XamlUrl    = "https://github.com/microsoft/microsoft-ui-xaml/releases/download/v2.7.3/Microsoft.UI.Xaml.2.7.x64.appx"
    $RuntimeUrl = "https://aka.ms/windowsappsdk/1.8/1.8.260921001/windowsappruntimeinstall-x64.exe"

    $VCLibsPath = "$BasePath\VCLibs.appx"
    $XamlPath   = "$BasePath\UI.Xaml.appx"
    $RuntimeExe = "$BasePath\Runtime.exe"
    $WingetPath = "$BasePath\Winget.msixbundle"

    function Install-WingetWindowsAppRuntime {
        Write-Host "  -> Instalando/actualizando Windows App Runtime 1.8..."
        Invoke-WebRequest $RuntimeUrl -OutFile $RuntimeExe -UseBasicParsing -ErrorAction Stop
        $runtimeProcess = Start-Process -FilePath $RuntimeExe -ArgumentList "/quiet" -Wait -PassThru -ErrorAction Stop
        if ($runtimeProcess.ExitCode -notin @(0, 3010)) {
            throw "El instalador de Windows App Runtime finalizo con codigo $($runtimeProcess.ExitCode)."
        }

        $minimumRuntimeVersion = [version]'8000.616.0.0'
        $runtimePackage = Get-AppxPackage -AllUsers -Name 'Microsoft.WindowsAppRuntime.1.8' -ErrorAction SilentlyContinue |
            Where-Object { $_.Architecture -in @('X64', 'Neutral') } |
            Sort-Object { [version]$_.Version } -Descending |
            Select-Object -First 1
        if (-not $runtimePackage -or [version]$runtimePackage.Version -lt $minimumRuntimeVersion) {
            $foundVersion = if ($runtimePackage) { $runtimePackage.Version } else { 'no detectado' }
            throw "Windows App Runtime 1.8 requerido >= $minimumRuntimeVersion; instalado: $foundVersion."
        }
        Write-Host "  -> Windows App Runtime disponible: $($runtimePackage.Version)"
    }

    # ===============================
    # OBTENER ÚLTIMA VERSIÓN DE WINGET DESDE GITHUB
    # ===============================
    Write-Host "Consultando la última versión de Winget en GitHub..."
    Write-WingetLog -Message "Consultando la última versión de Winget en GitHub."
    try {
        $githubRelease = Invoke-RestMethod `
            -Uri "https://api.github.com/repos/microsoft/winget-cli/releases/latest" `
            -Headers @{ 'User-Agent' = 'PowerShell' } `
            -ErrorAction Stop
        $asset = $githubRelease.assets |
            Where-Object { $_.name -match '\.msixbundle$' } |
            Select-Object -First 1
        $WingetUrl = $asset.browser_download_url

        if (-not $WingetUrl) {
            throw "No se encontró un archivo .msixbundle en la última versión."
        }
        Write-Host "Última versión encontrada: $($githubRelease.tag_name)"
    } catch {
        Write-Host "No se pudo consultar GitHub para obtener Winget. Revisa el log: $WingetLogPath" -ForegroundColor Red
        Write-WingetLog -Message "Error obteniendo la URL de Winget desde GitHub." -ErrorRecord $_
        return
    }

    $serverVersionText = [regex]::Match(
        [string]$githubRelease.tag_name,
        '\d+(?:\.\d+){1,3}'
    ).Value
    try {
        if (-not $serverVersionText) {
            throw "Formato de versión remota inválido: $($githubRelease.tag_name)"
        }
        $serverVersion = [version]$serverVersionText
    }
    catch {
        Write-Host "No se pudo interpretar la versión de Winget publicada. Revisa el log: $WingetLogPath" -ForegroundColor Red
        Write-WingetLog -Message "Error interpretando la versión publicada de Winget." -ErrorRecord $_
        return
    }

    try {
        $installedPackages = @(
            Get-AppxPackage -AllUsers -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue |
                Sort-Object { [version]$_.Version } -Descending
        )
        $installedPackage = $installedPackages | Select-Object -First 1
        $wingetExists = Test-WingetInstalled
        $currentVersion = [version]'0.0.0'

        if ($installedPackage) {
            $currentVersion = [version]$installedPackage.Version
        }

        if ($wingetExists) {
            $versionOutput = (& winget --version 2>$null | Out-String).Trim()
            $versionText = [regex]::Match($versionOutput, '\d+(?:\.\d+){1,3}').Value
            if ($versionText) {
                $commandVersion = [version]$versionText
                if ($commandVersion -gt $currentVersion) {
                    $currentVersion = $commandVersion
                }
            }
        }

        Write-Host "Winget local: $currentVersion | última versión: $serverVersion"
        if (($wingetExists -or $installedPackage) -and $currentVersion -ge $serverVersion) {
            Write-Host "Winget ya está en la última versión o es más reciente."
            Write-WingetLog -Message "Instalación omitida. Versión local: $currentVersion; versión publicada: $serverVersion."
            return
        }

        Write-WingetLog -Message "Iniciando instalación/actualización. Versión local: $currentVersion; versión publicada: $serverVersion."
        if (-not $installedPackage) {
            Write-Host "Winget no detectado. Instalando componentes necesarios..."

            if (Test-AppxPackageInstalled "Microsoft.VCLibs.140.00.UWPDesktop") {
                Write-Host "VCLibs ya instalado; se omite descarga."
            }
            else {
                Write-Host "Descargando e instalando VCLibs..."
                Invoke-WebRequest $VCLibsUrl -OutFile $VCLibsPath -UseBasicParsing -ErrorAction Stop
                Add-AppxPackage -Path $VCLibsPath -ErrorAction Stop
            }

            if (Test-AppxPackageInstalled "Microsoft.UI.Xaml") {
                Write-Host "Microsoft.UI.Xaml ya instalado; se omite descarga."
            }
            else {
                Write-Host "Descargando e instalando Microsoft.UI.Xaml..."
                Invoke-WebRequest $XamlUrl -OutFile $XamlPath -UseBasicParsing -ErrorAction Stop
                Add-AppxPackage -Path $XamlPath -ErrorAction Stop
            }
        }

        Install-WingetWindowsAppRuntime

        Write-Host "Descargando Winget $serverVersion..."
        Invoke-WebRequest $WingetUrl -OutFile $WingetPath -UseBasicParsing -ErrorAction Stop
        Write-Host "Instalando o actualizando Winget..."
        Add-AppxPackage -Path $WingetPath -ForceApplicationShutdown -ErrorAction Stop

        $updatedPackage = Get-AppxPackage -Name 'Microsoft.DesktopAppInstaller' -ErrorAction SilentlyContinue |
            Sort-Object { [version]$_.Version } -Descending |
            Select-Object -First 1
        if (-not $updatedPackage -or [version]$updatedPackage.Version -lt $serverVersion) {
            $updatedVersion = if ($updatedPackage) { $updatedPackage.Version } else { 'no detectada' }
            throw "Winget no quedo actualizado. Version detectada: $updatedVersion"
        }

        Write-Host "Winget instalado/actualizado correctamente a $($updatedPackage.Version)."
        Write-WingetLog -Message "Instalación/actualización completada correctamente. Versión instalada: $($updatedPackage.Version)."
    }
    catch {
        Write-Host "No se pudo instalar o actualizar Winget. Revisa el log: $WingetLogPath" -ForegroundColor Red
        Write-WingetLog -Message "Error durante la instalación/actualización de Winget." -ErrorRecord $_
    }
}

# ==========================================================
# EJECUCIÓN PRINCIPAL
# ==========================================================
Install-StoreIfNeeded

# Ejecutar Install-Winget siempre para permitir actualización, la función maneja la lógica si ya existe
Install-Winget

# ===============================
# LIMPIEZA DE TEMPORALES
# ===============================
Write-Host "Limpiando archivos temporales..."
Remove-Item $BasePath -Recurse -Force -ErrorAction SilentlyContinue
Write-Host "Limpieza completada"

# Script: detectar volumen donde está Windows y aplicar regla CompactOS
try {
    # Ruta Windows y unidad raíz (ej: "C:\Windows" -> "C:\")
    $winPath = (Get-Item $env:SystemRoot).FullName
    $root = [System.IO.Path]::GetPathRoot($winPath)

    # Intento 1: usar .NET DriveInfo
    try {
        $drive = New-Object System.IO.DriveInfo($root)
        if (-not $drive.IsReady) { throw "Drive not ready" }
        $totalBytes = $drive.TotalSize
    }
    catch {
        # Fallback: resolver ruta física del hive SYSTEM y extraer HarddiskN
        Add-Type -TypeDefinition @"
using System;
using System.Runtime.InteropServices;
using System.Text;
public static class PR {
    [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)]
    public static extern IntPtr CreateFile(string lpFileName, uint dwDesiredAccess, uint dwShareMode, IntPtr lpSecurityAttributes, uint dwCreationDisposition, uint dwFlagsAndAttributes, IntPtr hTemplateFile);
    [DllImport("kernel32.dll", SetLastError=true, CharSet=CharSet.Unicode)]
    public static extern uint GetFinalPathNameByHandle(IntPtr hFile, StringBuilder lpszFilePath, uint cchFilePath, uint dwFlags);
    [DllImport("kernel32.dll", SetLastError=true)]
    public static extern bool CloseHandle(IntPtr hObject);
}
"@ -ErrorAction SilentlyContinue

        $systemHive = Join-Path $env:SystemRoot "System32\config\SYSTEM"
        if (-not (Test-Path $systemHive)) { throw "No SYSTEM hive found" }

        $FILE_READ_ATTRIBUTES = [uint32]0x80
        $SHARE = [uint32]($([uint32]1) -bor $([uint32]2) -bor $([uint32]4))
        $OPEN_EXISTING = [uint32]3
        $BACKUP = [uint32]0x02000000

        $h = [PR]::CreateFile($systemHive, $FILE_READ_ATTRIBUTES, $SHARE, [IntPtr]::Zero, $OPEN_EXISTING, $BACKUP, [IntPtr]::Zero)
        if ($h -eq [IntPtr]::Zero -or $h.ToInt64() -eq -1) { throw "CreateFile failed (sharing or privileges)" }

        $sb = New-Object System.Text.StringBuilder 1024
        $res = [PR]::GetFinalPathNameByHandle($h, $sb, [uint32]$sb.Capacity, 0)
        [PR]::CloseHandle($h) | Out-Null
        if ($res -eq 0) { throw "GetFinalPathNameByHandle failed" }

        $phys = $sb.ToString()
        if ($phys -match "Harddisk(\d+)\\Partition") {
            $diskNumber = [int]$matches[1]
            # intentar Get-Disk por número (puede fallar en algunos contextos)
            $disk = Get-Disk -Number $diskNumber -ErrorAction SilentlyContinue
            if ($disk) { $totalBytes = $disk.Size } else { throw "No se pudo mapear disco físico" }
        }
        else { throw "No se pudo extraer HarddiskN" }
    }

    # Convertir a GB y aplicar lógica
    $sizeGB = [math]::Round($totalBytes / 1GB)
    Write-Host "Volumen raíz: $root  —  Tamaño total: $sizeGB GB"

    if ($sizeGB -le 64) {
        Write-Host "El disco es menor o igual a 64GB. CompactOS NO se modifica."
    }
    elseif ($sizeGB -ge 100) {
        Write-Host "El disco es mayor o igual a 100GB. CompactOS sera DESACTIVADO..."
        compact.exe /compactos:never
    }
    else {
        Write-Host "El disco esta entre 65GB y 99GB. No se realiza ninguna accion."
    }
}
catch {
    Write-Host "Error: $($_.Exception.Message)"
    exit 1
}

##=============================================================================
## PROCESO DE ELEVACIÓN Y CONFIGURACIÓN INICIAL
##=============================================================================
function Test-Admin {
    $currentIdentity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object Security.Principal.WindowsPrincipal($currentIdentity)
    return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
}

if (-not (Test-Admin)) {
    Write-Host "Solicitando permisos de Administrador..." -ForegroundColor Yellow
    $scriptPath = $MyInvocation.MyCommand.Path
    Start-Process powershell -ArgumentList "-NoProfile -ExecutionPolicy Bypass -File `"$scriptPath`"" -Verb RunAs
    exit
}

[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
Set-ExecutionPolicy -Scope Process -ExecutionPolicy Bypass -Force
$ProgressPreference = 'SilentlyContinue' # Oculta progresos nativos ruidosos para usar el nuestro
$logFile = "C:\Updates.log"

function Write-Log($Message) {
    $timestamp = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $line = "[$timestamp] $Message"
    Write-Host $Message -ForegroundColor Cyan
    Add-Content -Path $logFile -Value $line -Encoding UTF8
}

##=============================================================================
## MOTOR DE ACTUALIZACIONES (FASES 1 a 5)
##=============================================================================

try {
    Write-Log "-------------------------------------------------------"
    Write-Log "--- FASE 1: Instalando y preparando PSWindowsUpdate ---"
    Write-Log "-------------------------------------------------------"
    if (-not (Get-PackageProvider -Name NuGet -ErrorAction SilentlyContinue)) {
        Install-PackageProvider -Name NuGet -MinimumVersion 2.8.5.201 -Force -Scope AllUsers -ErrorAction Stop
    }

    $psGallery = Get-PSRepository -Name PSGallery -ErrorAction SilentlyContinue
    if ($null -eq $psGallery -or $psGallery.InstallationPolicy -ne 'Trusted') {
        Set-PSRepository -Name PSGallery -InstallationPolicy Trusted -ErrorAction Stop
    }

    if (-not (Get-Module -ListAvailable -Name PSWindowsUpdate)) {
        Install-Module -Name PSWindowsUpdate -Force -AllowClobber -Confirm:$false -ErrorAction Stop
    }
    Import-Module PSWindowsUpdate -Force -ErrorAction Stop

    # Habilitar servicio para que encuentre drivers de fabricantes de terceros
    Add-WUServiceManager -ServiceID "7971f918-a847-4430-9279-4a52d1efe18d" -Confirm:$false -ErrorAction SilentlyContinue | Out-Null
    $drvPath = "HKLM:\SOFTWARE\Microsoft\Windows\CurrentVersion\DriverSearching"
    if (-not (Test-Path $drvPath)) { New-Item -Path $drvPath -Force | Out-Null }
    Set-ItemProperty -Path $drvPath -Name "SearchOrderConfig" -Value 1 -Type DWord -ErrorAction Stop


    # Array donde guardaremos todo lo encontrado antes de descargar/instalar
    $listaActualizaciones = @()

    Write-Log "---------------------------------------------------"
    Write-Log "--- FASE 2: Buscando actualizaciones de Drivers ---"
    Write-Log "---------------------------------------------------"
    $drivers = Get-WindowsUpdate -MicrosoftUpdate -Category "Drivers" -ErrorAction SilentlyContinue
    if ($drivers) { 
        $listaActualizaciones += $drivers 
        Write-Log "!! Se encontraron $($drivers.Count) Drivers. !!"
    } else {
        Write-Log "-> No se encontraron Drivers."
    }

    Write-Log "---------------------------------------------------------------"
    Write-Log "--- FASE 3: Buscando Definiciones y Otros (Excluyendo MSRT) ---"
    Write-Log "---------------------------------------------------------------"
    $otros = Get-WindowsUpdate -MicrosoftUpdate -NotCategory "Drivers" -ErrorAction SilentlyContinue
    if ($otros) {
        # Excluir solo la herramienta de eliminación de software malintencionado.
        # Las acumulativas y de seguridad se conservan para compararlas con la
        # revisión completa instalada (Build.UBR) más abajo.
        $otrosFiltrados = $otros | Where-Object {
            $_.Title -notmatch "Malicious Software Removal Tool|eliminación de software malintencionado"
        }
        $listaActualizaciones += $otrosFiltrados
        Write-Log " !! Se encontraron $($otrosFiltrados.Count) actualizaciones vlidas. !!"
    } else {
        Write-Log "-> No se encontraron otras actualizaciones."
    }

    # Omitir versiones/builds que ya están instaladas. Para acumulativas y
    # actualizaciones de seguridad comparar Build.UBR, porque el build base
    # (por ejemplo 26300) puede ser el mismo aunque haya una revisión más nueva.
    $osInfo = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction Stop
    $installedBuild = [string]$osInfo.BuildNumber
    $osVersionKey = 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion'
    $currentVersion = Get-ItemProperty -Path $osVersionKey -ErrorAction SilentlyContinue
    $installedUBR = 0
    if ($null -ne $currentVersion.UBR) {
        $installedUBR = [int]$currentVersion.UBR
    }
    $installedDisplayVersion = [string]$currentVersion.DisplayVersion
    if ([string]::IsNullOrWhiteSpace($installedDisplayVersion)) {
        $installedDisplayVersion = [string]$currentVersion.ReleaseId
    }

    $updatesBeforeBuildFilter = $listaActualizaciones.Count
    $listaActualizaciones = @($listaActualizaciones | Where-Object {
        $updateText = "$( $_.Title ) $( $_.Description )"
        $matchesInstalledBuild = $false
        $isCumulativeOrSecurity = $updateText -match '(?i)cumulative|acumulativa|security update|actualizaci[oó]n de seguridad'

        if (-not $isCumulativeOrSecurity -and $installedDisplayVersion -and
            $updateText -match '(?i)(?:version|versi[oó]n)\s*(?<version>\d{2}H\d)') {
            if ($matches['version'] -ieq $installedDisplayVersion) {
                $matchesInstalledBuild = $true
            }
        }

        if (-not $matchesInstalledBuild -and $installedBuild -and
            $updateText -match '(?i)(?:OS\s*)?(?:build|compilaci[oó]n)\s*(?:number|n[uú]mero)?\s*[:#]?\s*(?<build>\d{5})(?:\.(?<ubr>\d{1,5}))?') {
            $updateBuild = $matches['build']
            $hasUpdateUBR = -not [string]::IsNullOrWhiteSpace($matches['ubr'])

            if ($updateBuild -eq $installedBuild) {
                if ($isCumulativeOrSecurity) {
                    # Sin UBR explícito no se puede afirmar que una LCU esté ya instalada.
                    if ($hasUpdateUBR -and [int]$matches['ubr'] -le $installedUBR) {
                        $matchesInstalledBuild = $true
                    }
                } elseif (-not $hasUpdateUBR -or [int]$matches['ubr'] -le $installedUBR) {
                    $matchesInstalledBuild = $true
                }
            }
        }

        if ($matchesInstalledBuild) {
            Write-Log "-> Omitida por corresponder a la version/build ya instalada ($installedDisplayVersion, compilacion $installedBuild.$installedUBR): $($_.Title)"
            return $false
        }
        return $true
    })
    $skippedBaseUpdates = $updatesBeforeBuildFilter - $listaActualizaciones.Count
    if ($skippedBaseUpdates -gt 0) {
        Write-Log "-> Se omitieron $skippedBaseUpdates actualizaciones que corresponden a la version/build instalada ($installedDisplayVersion, compilacion $installedBuild.$installedUBR)."
    }

    # Validar si hay algo que hacer
    if ($listaActualizaciones.Count -eq 0) {
        Write-Log "No hay actualizaciones pendientes con los criterios solicitados."
        Write-Log "Todo listo. Drivers y actualizaciones aplicadas."
        exit
    }

    Write-Log "--------------------------------------"
    Write-Log "--- FASE 4: Listando y Descargando ---"
    Write-Log "--------------------------------------"
    Write-Log ""
    Write-Log "-----------------------------------------------"
    Write-Log "Total a procesar: $($listaActualizaciones.Count) actualizaciones."
    Write-Log "-----------------------------------------------"
    foreach ($upd in $listaActualizaciones) {
        Write-Log " [Pendiente] $($upd.Title)"
    }

    $ProgressPreference = 'Continue'
    Write-Log "-----------------------------------------------"
    Write-Log "Iniciando descarga estricta en segundo plano..."
    Write-Log "-----------------------------------------------"
    # Descarga obligando al módulo a buscar solo el KB o Título exacto filtrado
    foreach ($update in $listaActualizaciones) {
        if ($update.KBArticleID) {
            Get-WindowsUpdate -KBArticleID $update.KBArticleID -Download -AcceptAll -IgnoreReboot -ErrorAction SilentlyContinue | Out-Null
        } else {
            # Los drivers a veces no tienen KB, usamos el título exacto
            Get-WindowsUpdate -Title $update.Title -Download -AcceptAll -IgnoreReboot -ErrorAction SilentlyContinue | Out-Null
        }
    }
    Write-Log ""
    Write-Log "--------------------------------------------------"
    Write-Log "--- FASE 5: Instalando la secuencia descargada ---"
    Write-Log "--------------------------------------------------"
    $total = $listaActualizaciones.Count
    $contador = 1

    foreach ($update in $listaActualizaciones) {
        $porcentaje = [math]::Round(($contador / $total) * 100)
        Write-Progress -Activity "Instalando actualizaciones (Fase 5)" -Status "Progreso general: $contador de $total" -PercentComplete $porcentaje -CurrentOperation $update.Title

        Write-Log " -> Instalando [$contador/$total]: $($update.Title)"

        # Instalación estricta usando el identificador
        if ($update.KBArticleID) {
            Install-WindowsUpdate -KBArticleID $update.KBArticleID -AcceptAll -IgnoreReboot -ErrorAction SilentlyContinue | Out-Null
        } else {
            Install-WindowsUpdate -Title $update.Title -AcceptAll -IgnoreReboot -ErrorAction SilentlyContinue | Out-Null
        }

        $contador++
    }

    Write-Progress -Activity "Instalando actualizaciones (Fase 5)" -Completed
    Write-Log "Todo listo. Drivers y actualizaciones aplicadas."

} catch {
    Write-Log "ERROR CRÍTICO: $_"
}

 $firstLogonOutputLog = 'C:\Windows\Setup\Scripts\FirstLogon.log'
 $utf8WithBom = New-Object System.Text.UTF8Encoding($true)
 if (Test-Path -LiteralPath $firstLogonOutputLog) {
     $existingLogText = [System.IO.File]::ReadAllText($firstLogonOutputLog)
     [System.IO.File]::WriteAllText($firstLogonOutputLog, $existingLogText, $utf8WithBom)
 } else {
     [System.IO.File]::WriteAllBytes($firstLogonOutputLog, $utf8WithBom.GetPreamble())
 }

& {
    $ErrorActionPreference = 'Stop'
    [Console]::OutputEncoding = [System.Text.UTF8Encoding]::new($false)

    # --- ELEVAR A ADMINISTRADOR ---
    $currentUser = [Security.Principal.WindowsIdentity]::GetCurrent()
    $windowsPrincipal = New-Object Security.Principal.WindowsPrincipal($currentUser)
    if (-not $windowsPrincipal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        $arguments = "-NoProfile -ExecutionPolicy Bypass -File `"$PSCommandPath`""
        Start-Process -FilePath 'powershell.exe' -ArgumentList $arguments -Verb RunAs
        return
    }

    # --- CONFIGURACIÓN INICIAL ---
    $scriptDir   = 'C:\Windows\Setup\Scripts'
    $stateFile   = Join-Path $scriptDir 'state.json'
    $logFilePath = Join-Path $scriptDir 'FirstLogon_1.log'
    $equipoLog   = Join-Path $scriptDir 'Equipo.log'

    if (-not (Test-Path -LiteralPath $scriptDir)) {
        New-Item -ItemType Directory -Path $scriptDir -Force | Out-Null
    }

    function Write-Log {
        param([Parameter(Mandatory = $true)][string]$Message)
        $line = '[{0}] {1}' -f (Get-Date -Format 'yyyy-MM-dd HH:mm:ss'), $Message
        # Tee-Object al final del controlador escribe cada línea en FirstLogon.log.
        Write-Output $line
    }

    function Save-State {
        param([Parameter(Mandatory = $true)]$Items)
        $tempFile = "$stateFile.tmp"
        ConvertTo-Json -InputObject @($Items) -Depth 10 |
            Set-Content -LiteralPath $tempFile -Encoding UTF8
        Move-Item -LiteralPath $tempFile -Destination $stateFile -Force
    }


    function Invoke-LocalScript {
        param([Parameter(Mandatory = $true)][string]$Name)

        $path = Join-Path $scriptDir $Name

        if (-not (Test-Path -LiteralPath $path -PathType Leaf)) {
            throw "No se encuentra el script requerido: $path"
        }

        # Crear únicamente la carpeta Logs, sin subcarpetas.
        if (-not $script:runLogsDir) {
            $script:runLogsDir = Join-Path $scriptDir 'Logs'

            if (-not (Test-Path -LiteralPath $script:runLogsDir -PathType Container)) {
                New-Item -ItemType Directory -Path $script:runLogsDir -Force |
                    Out-Null
            }
        }

        Write-Log "Ejecutando $Name dentro de la fase activa."

        $content = Get-Content -LiteralPath $path -Raw -ErrorAction Stop

        if ([string]::IsNullOrWhiteSpace($content)) {
            throw "El script está vacío: $path"
        }

        Invoke-Expression -Command $content

        Write-Log "Finalizó la invocación de $Name."
    }

    try {
        Add-Content -LiteralPath $logFilePath -Value "`r`n=== Inicio de ejecución: $(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') ===" -Encoding UTF8
    } catch {
        Write-Output "No se pudo escribir el separador del registro: $($_.Exception.Message)"
    }

    # --- TAREAS ---
    # Optimizar unidades y Optimizar Windows son tareas normales e independientes.
    $scripts = @(
        @{ Name = 'Remove Windows.old'
            Script = {
                $oldPath = 'C:\Windows.old'
                if (Test-Path -LiteralPath $oldPath) {
                    Write-Log 'Intentando eliminar C:\Windows.old...'
                    & cmd.exe /c 'rmdir C:\Windows.old /s /q'
                    if (Test-Path -LiteralPath $oldPath) {
                        Write-Log 'Aviso: C:\Windows.old sigue existiendo; Windows puede impedir su eliminación.'
                    } else { Write-Log 'C:\Windows.old eliminado.' }
                } else { Write-Log 'C:\Windows.old no existe; se omite.' }
            }
        },
        @{ Name = 'Cambiando ID Equipo'
		    Script = {
		        # Equipo.log debe ser creado por ChangePC-ID.ps1 al completar su operación.
		        # Si el equipo se reinicia dentro de ese script, esta tarea se reintentará al volver.
		        if (Test-Path -LiteralPath $equipoLog) {
		            Write-Log 'Equipo.log ya existe; se omite ChangePC-ID.ps1.'
		            return
		        }

		        Invoke-LocalScript -Name 'ChangePC-ID.ps1'

		        Write-Log 'ChangePC-ID.ps1 finalizado. Windows se reiniciará en 5 segundos para aplicar el cambio de nombre.'
		        Start-Sleep -Seconds 5
		        Restart-Computer -Force
		    }
		},
        @{ Name = 'Verificando Sistema'; Script = { Invoke-LocalScript -Name 'unattend-02.ps1' } },
        @{ Name = 'Verificando Configuracion'; Script = { Invoke-LocalScript -Name 'verifyconfig.ps1' } },
        @{ Name = 'Comprobar Integridad'; Script = { Invoke-LocalScript -Name 'Integrity.ps1' } },
        @{ Name = 'Cambiando Cursor'; Script = { Invoke-LocalScript -Name 'CursorVista.ps1' } },
        @{ Name = 'Instalando Actualizaciones'; Script = { Invoke-LocalScript -Name 'PSUpdates.ps1' } },
        @{ Name = 'Instalando Apps + VCLibs'; Script = { Invoke-LocalScript -Name 'Installappcore.ps1' } },
        @{ Name = 'Instalando Office 365'; Script = { Invoke-LocalScript -Name 'OfficeInstaller.ps1' } },
        @{ Name = 'Optimizando Windows'; Script = { Invoke-LocalScript -Name 'OptimizarWindows.ps1' } },
        @{ Name = 'Instalando Rustdesk'; Script = { Invoke-LocalScript -Name 'Rustdesk_Download.ps1' } },
		@{ Name = 'Optimizando Discos'; Script = { Invoke-LocalScript -Name 'OptimizeDrive.ps1' } },
        @{ Name = 'Finalizado'
            Script = {
                # Preservar el controlador, lanzador, estado y registros.
                $protectedNames = @('FirstLogon.ps1', 'Launcher.ps1', 'state.json', 'FirstLogon.log', 'Equipo.log')
                Write-Log 'Iniciando limpieza final de archivos auxiliares...'
                Get-ChildItem -LiteralPath $scriptDir -Recurse -File -Force -ErrorAction SilentlyContinue |
                    Where-Object {
                        $_.Extension -in @('.ps1', '.vbs', '.xml') -and
                        $protectedNames -notcontains $_.Name
                    } |
                    ForEach-Object {
                        try {
                            Write-Log "Eliminando archivo auxiliar: $($_.FullName)"
                            Remove-Item -LiteralPath $_.FullName -Force -ErrorAction Stop
                        } catch { Write-Log "No se pudo eliminar $($_.FullName): $($_.Exception.Message)" }
                    }
                Write-Log 'Limpieza final completada.'
            }
        }
    )

    # --- ESTADO ---
    if (-not (Test-Path -LiteralPath $stateFile)) {
        $state = @(
            for ($index = 0; $index -lt $scripts.Count; $index++) {
                [PSCustomObject]@{ index = $index; name = $scripts[$index].Name; status = 'pending'; attempts = 0 }
            }
        )
        Save-State -Items $state
        Write-Log 'Se creó state.json con el estado inicial.'
    } else {
        try {
            $loaded = Get-Content -LiteralPath $stateFile -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
            $state = @($loaded)
        } catch {
            Write-Log "ERROR: state.json no se puede leer como JSON válido: $($_.Exception.Message)"
            throw
        }

        # Actualizar el estado por nombre: así se conservan tareas ya completadas
        # y se crean las nuevas cuando cambia la lista del controlador.
        $previousByName = @{}
        foreach ($previousTask in $state) {
            $previousName = [string]$previousTask.name
            if (-not [string]::IsNullOrWhiteSpace($previousName)) {
                $previousByName[$previousName] = $previousTask
            }
        }

        $updatedState = @(
            for ($index = 0; $index -lt $scripts.Count; $index++) {
                $taskName = [string]$scripts[$index].Name
                $oldTask = $previousByName[$taskName]
                $taskStatus = if ($oldTask -and [string]$oldTask.status -in @('done', 'running', 'error', 'pending-reboot')) {
                    [string]$oldTask.status
                } else {
                    'pending'
                }
                $taskAttempts = 0
                if ($oldTask -and $null -ne $oldTask.attempts) {
                    try { $taskAttempts = [Math]::Max(0, [int]$oldTask.attempts) } catch { $taskAttempts = 0 }
                }
                # Los errores de versiones anteriores no guardaban intentos; permitirles
                # entrar al nuevo flujo de dos intentos en vez de omitirlos directamente.
                if ($oldTask -and [string]$oldTask.status -eq 'error' -and $null -eq $oldTask.attempts) {
                    $taskStatus = 'pending'
                }
                [PSCustomObject]@{ index = $index; name = $taskName; status = $taskStatus; attempts = $taskAttempts }
            }
        )

        $stateChanged = $state.Count -ne $updatedState.Count
        if (-not $stateChanged) {
            for ($index = 0; $index -lt $updatedState.Count; $index++) {
                if ([int]$state[$index].index -ne $index -or
                    [string]$state[$index].name -ne [string]$updatedState[$index].name -or
                    [string]$state[$index].status -ne [string]$updatedState[$index].status -or
                    [int]$state[$index].attempts -ne [int]$updatedState[$index].attempts) {
                    $stateChanged = $true
                    break
                }
            }
        }
        $state = $updatedState
        if ($stateChanged) {
            Save-State -Items $state
            Write-Log "state.json actualizado: $($state.Count) tareas sincronizadas con esta versión."
        }
    }

    Write-Log "Controlador iniciado. Tareas configuradas: $($scripts.Count)."

    for ($i = 0; $i -lt $scripts.Count; $i++) {
        $status = [string]$state[$i].status
        if ($status -eq 'done') {
            Write-Log "Omitiendo tarea completada: $($scripts[$i].Name)."
            continue
        }
        if ($status -eq 'error') {
            Write-Log "La tarea '$($scripts[$i].Name)' ya agotó sus intentos; se omite y continúa el flujo."
            continue
        }
        if ([int]$state[$i].attempts -ge 2) {
            $state[$i].status = 'error'
            Save-State -Items $state
            Write-Log "La tarea '$($scripts[$i].Name)' no se completó dentro de sus 2 intentos; se omite y continúa el flujo."
            continue
        }

        $completed = $false
        $retryOnNextStart = $false
        while (-not $completed -and [int]$state[$i].attempts -lt 2) {
            $state[$i].attempts = [int]$state[$i].attempts + 1
            $state[$i].status = 'running'
            Save-State -Items $state
            Write-Log "Iniciando tarea $($i + 1)/$($scripts.Count): $($scripts[$i].Name) (intento $($state[$i].attempts)/2)."

            if (-not $script:runLogsDir) {
                $script:runLogsDir = Join-Path $scriptDir 'Logs'
                if (-not (Test-Path -LiteralPath $script:runLogsDir -PathType Container)) {
                    New-Item -ItemType Directory -Path $script:runLogsDir -Force |
                        Out-Null
                }
            }

            $phaseLogName = $scripts[$i].Name
            foreach ($invalidLogCharacter in [IO.Path]::GetInvalidFileNameChars()) {
                $phaseLogName = $phaseLogName.Replace([string]$invalidLogCharacter, '_')
            }
            $phaseLogPath = Join-Path $script:runLogsDir ($phaseLogName + '.log')
            $transcriptStarted = $false
            try {
                Start-Transcript -Path $phaseLogPath -Append -Force -ErrorAction Stop |
                    Out-Null
                $transcriptStarted = $true

                & $scripts[$i].Script

                $state[$i].status = 'done'
                Save-State -Items $state
                Write-Log "Tarea completada: $($scripts[$i].Name)."
                $completed = $true
            } catch {
                $errorMessage = $_.Exception.Message
                if ([int]$state[$i].attempts -lt 2) {
                    $state[$i].status = 'pending'
                    Save-State -Items $state
                    Write-Log "ERROR en '$($scripts[$i].Name)' (intento $($state[$i].attempts)/2): $errorMessage. Se reintentará cuando se vuelva a iniciar FirstLogon."
                    $retryOnNextStart = $true
                    break
                } else {
                    $state[$i].status = 'error'
                    try { Save-State -Items $state } catch {}
                    Write-Log "ERROR definitivo en '$($scripts[$i].Name)' tras 2 intentos: $errorMessage. Se omite y continúa el flujo."
                }
            }
            finally {
                if ($transcriptStarted) {
                    Stop-Transcript -ErrorAction SilentlyContinue |
                        Out-Null
                }
            }

        }

        if ($retryOnNextStart) {
            Write-Log "El controlador se detiene para permitir el reintento de '$($scripts[$i].Name)' en la próxima ejecución."
            break
        }
    }

    $notDone = @($state | Where-Object { $_.status -ne 'done' })
    if ($notDone.Count -eq 0) {
        Write-Log 'Todas las tareas están marcadas como completadas.'
    } else {
        Write-Log ('El flujo no ha terminado. Tareas pendientes o con error: ' + (($notDone | ForEach-Object { "$($_.name)=$($_.status)" }) -join '; '))
    }

    Write-Log 'El controlador no fuerza un reinicio; las tareas ejecutadas pueden reiniciar Windows si lo solicitan explícitamente.'
} 2>&1 | ForEach-Object {
    $line = [string]$_
    Add-Content -LiteralPath "C:\Windows\Setup\Scripts\FirstLogon.log" -Value $line -Encoding UTF8
    $line
}
